{"CommandLine":"$dir = "C:\Users\renu5\.gemini\antigravity\conversations"
$dbs = Get-ChildItem -Path $dir -Filter "*.db"
foreach ($db in $dbs) {
    # It might be easier to use sqlite3 if it's installed, or use strings.
    # We can just read the file content with Select-String since we are looking for a UUID.
    $match = Select-String -Path $db.FullName -Pattern "133e05e6-4851-4798-955d-f3be3448d8ee" -Quiet
    if ($match) {
        Write-Output "Found in $($db.FullName)"
    }
}
